1	import * as React from "react";
2	
3	export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
4	  /** Render as a different element (e.g. "section", "article", "li"). */
5	  as?: React.ElementType;
6	}
7	
8	/**
9	 * White card on warm paper: 1px warm border + soft low shadow, 16px radius.
10	 * Structural separation comes from the border; the shadow is gentle lift.
11	 */
12	export function Card({
13	  as: Tag = "div",
14	  className = "",
15	  children,
16	  ...rest
17	}: CardProps) {
18	  return (
19	    <Tag
20	      className={[
21	        "rounded-card border border-border bg-surface p-5 shadow-sm",
22	        className,
23	      ]
24	        .filter(Boolean)
25	        .join(" ")}
26	      {...rest}
27	    >
28	      {children}
29	    </Tag>
30	  );
31	}
