7	import { t } from "@/lib/i18n";
8	import { useToast } from "@/components/ui/Toast";
9	
10	/**
11	 * Large, unmistakable "Available now" switch. State is conveyed by an icon and
12	 * a text label (never colour alone), announced on change, and operable by
13	 * keyboard via the underlying role="switch".
14	 */
15	export function AvailabilityToggle({
16	  initial,
17	  disabled,
18	}: {
19	  initial: boolean;
20	  disabled?: boolean;
21	}) {
22	  const [on, setOn] = React.useState(initial);
23	  const [pending, startTransition] = useTransition();
24	  const { announce } = useToast();
25	
26	  function flip() {
27	    const next = !on;
28	    setOn(next);
29	    announce(next ? t("provider.available") : t("provider.offline"), true);
30	    startTransition(async () => {
31	      const res = await setAvailability(next);
32	      if (!res.ok) setOn(!next); // revert on failure
33	    });
34	  }
35	
36	  if (disabled) {
37	    return (
38	      <p className="rounded-card border border-border bg-surface-sunk px-4 py-3 text-base text-ink-soft">
39	        {t("provider.availableNotApproved")}
40	      </p>
41	    );
42	  }
43	
44	  return (
45	    <div className="flex flex-col gap-3">
46	      <button
47	        type="button"
48	        role="switch"
49	        aria-checked={on}
50	        onClick={flip}
51	        disabled={pending}
52	        className={[
53	          "flex min-h-12 w-full items-center justify-between gap-3 rounded-card border-2 px-5 py-4 text-left text-lg font-bold transition-colors",
54	          on
55	            ? "border-success bg-success-tint text-success"
56	            : "border-border-strong bg-surface text-ink",
57	        ].join(" ")}
58	      >
59	        <span className="flex items-center gap-2.5">
60	          {on ? (
61	            <CircleCheck size={24} strokeWidth={2} aria-hidden="true" />
62	          ) : (
63	            <Moon size={24} strokeWidth={2} aria-hidden="true" />
64	          )}
65	          {on ? t("provider.available") : t("provider.offline")}
66	        </span>
67	        <span className="text-base font-bold text-ink-soft">
68	          {on ? t("provider.turnOff") : t("provider.turnOn")}
69	        </span>
70	      </button>
71	    </div>
72	  );
73	}
