import "server-only";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { PUBLIC_PROVIDER_COLUMNS } from "@/lib/supabase/types";
import {
  type AdminMetricsAlerts,
  type AdminMetricsOperational,
  type AdminMetricsStrategic,
  type AvailabilitySlotRow,
  type BookingRow,
  type PaymentRow,
  type PayoutRow,
  type ProfileRow,
  type ProviderRow,
  type PublicProvider,
  type ReportRow,
  type ReviewRow,
  type SessionRow,
} from "@/lib/supabase/types";
import { type BrowseFilters } from "@/lib/validation/schemas";

/**
 * Central data-access layer (CLAUDE.md). All reads go through the RLS-enforced
 * server client, so each caller only sees rows they're entitled to. Public
 * provider reads select PUBLIC_PROVIDER_COLUMNS — never the server-only
 * bg_check_ref / payout_account_ref (no column-level RLS, so we scope here).
 */

/** Approved providers for discovery, with optional filters. */
export async function listApprovedProviders(
  filters: BrowseFilters = {},
): Promise<PublicProvider[]> {
  const supabase = await createClient();
  let query = supabase
    .from("providers")
    .select(PUBLIC_PROVIDER_COLUMNS)
    .eq("status", "approved");

  if (filters.topic) query = query.contains("topics", [filters.topic]);
  if (filters.language) query = query.contains("languages", [filters.language]);
  if (filters.availableNow) query = query.eq("is_available_now", true);
  if (typeof filters.maxPriceCents === "number") {
    query = query.lte("price_block_30_cents", filters.maxPriceCents);
  }

  const { data, error } = await query.order("rating_avg", { ascending: false });
  if (error) throw error;
  return (data ?? []) as unknown as PublicProvider[];
}

/** A single approved provider's public profile, or null. */
export async function getApprovedProvider(
  id: string,
): Promise<PublicProvider | null> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("providers")
    .select(PUBLIC_PROVIDER_COLUMNS)
    .eq("id", id)
    .eq("status", "approved")
    .maybeSingle();
  if (error) throw error;
  return (data as unknown as PublicProvider | null) ?? null;
}

/** Providers in a given status (admin only — RLS lets admins read all). */
export async function listProvidersByStatus(
  status: ProviderRow["status"],
): Promise<ProviderRow[]> {
  const supabase = await createClient();
  const { data, error } = await supabase
    .from("providers")
    .select("*")
    .eq("status", status)
    .order("created_at", { ascending: true });
  if (error) throw error;
  return data ?? [];
}

export interface AdminMetrics {
  strategic: AdminMetricsStrategic;
  operational: AdminMetricsOperational;
  alerts: AdminMetricsAlerts;
}

/**
 * Read the precomputed admin metric views. Access to the views is revoked from
 * anon/authenticated, so this uses the service-role client — callers MUST guard
 * with requireRole("admin") first.
 */
export async function getAdminMetrics(): Promise<AdminMetrics> {
  const admin = createAdminClient();
  const [strategic, operational, alerts] = await Promise.all([
    admin.from("admin_metrics_strategic").select("*").single(),
    admin.from("admin_metrics_operational").select("*").single(),
    admin.from("admin_metrics_alerts").select("*").single(),
  ]);
  if (strategic.error) throw strategic.error;
  if (operational.error) throw operational.error;
  if (alerts.error) throw alerts.error;

